//! Device features: per-device capability data from the buttplug
//! device config ache's runtime actually loads.
//!
//! `data/features.tsv` is generated by `tools/generate_features.py`
//! from the pinned `buttplug_server_device_config` crate's
//! build-config (v5) — the same embedded config the Phase 0 census
//! verified ache inherits wholesale. Nothing in this file invents a
//! capability: a device whose config could not be matched carries
//! [`MatchKind::None`] and an empty output list, and the UI says so.
//!
//! Rows are emitted in catalogue order and joined to
//! [`crate::catalogue`] rows by index; the test suite asserts the
//! (brand, device) pairs agree, so a bad regeneration fails loudly.

use std::fmt;

/// The generated features table, embedded at compile time.
pub const FEATURES_TSV: &str = include_str!("../data/features.tsv");

/// Fields per features row: brand, device, family, match, outputs,
/// inputs.
pub const FIELD_COUNT: usize = 6;

/// How a catalogue row was matched to a buttplug config entry (see
/// the generator for the exact rules). Recorded, never hidden: the
/// guide text names the basis of what it states.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum MatchKind {
    /// Config name equals "brand + device" (normalised).
    Exact,
    /// Matched after stripping a trailing generation token
    /// (catalogue "Edge 2" vs config "Lovense Edge").
    Generation,
    /// Config name equals the device name alone.
    NameOnly,
    /// Resolved through the protocol defaults (generic-config rows).
    ProtocolDefault,
    /// No config entry could be matched. Feature claims for this
    /// device would be invention, so there are none.
    None,
}

impl MatchKind {
    fn parse(text: &str) -> Option<MatchKind> {
        match text {
            "exact" => Some(MatchKind::Exact),
            "gen" => Some(MatchKind::Generation),
            "name" => Some(MatchKind::NameOnly),
            "default" => Some(MatchKind::ProtocolDefault),
            "none" => Some(MatchKind::None),
            _ => Option::None,
        }
    }

    /// Short label for the UI's provenance line.
    pub fn label(self) -> &'static str {
        match self {
            MatchKind::Exact => "matched exactly to the maker's published device data",
            MatchKind::Generation => {
                "matched to the maker's device data for this model's generation"
            }
            MatchKind::NameOnly => "matched by name only — treat the details as approximate",
            MatchKind::ProtocolDefault => "filled in from the maker's standard protocol defaults",
            MatchKind::None => "no maker data found — nothing here is invented",
        }
    }
}

/// One actuator kind, using the buttplug platform's output vocabulary
/// (docs.buttplug.io device/feature model). The plain-language verbs
/// are how the guide talks about them; the step ranges are the
/// config's own numbers.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ActuatorKind {
    Vibrate,
    Oscillate,
    Rotate,
    Constrict,
    Inflate,
    Position,
    HwPositionWithDuration,
    Temperature,
    Spray,
    Led,
}

impl ActuatorKind {
    fn parse(text: &str) -> Option<ActuatorKind> {
        match text {
            "vibrate" => Some(ActuatorKind::Vibrate),
            "oscillate" => Some(ActuatorKind::Oscillate),
            "rotate" => Some(ActuatorKind::Rotate),
            "constrict" => Some(ActuatorKind::Constrict),
            "inflate" => Some(ActuatorKind::Inflate),
            "position" => Some(ActuatorKind::Position),
            "hw_position_with_duration" => Some(ActuatorKind::HwPositionWithDuration),
            "temperature" => Some(ActuatorKind::Temperature),
            "spray" => Some(ActuatorKind::Spray),
            "led" => Some(ActuatorKind::Led),
            _ => Option::None,
        }
    }

    /// The config's own token for this kind.
    pub fn token(self) -> &'static str {
        match self {
            ActuatorKind::Vibrate => "vibrate",
            ActuatorKind::Oscillate => "oscillate",
            ActuatorKind::Rotate => "rotate",
            ActuatorKind::Constrict => "constrict",
            ActuatorKind::Inflate => "inflate",
            ActuatorKind::Position => "position",
            ActuatorKind::HwPositionWithDuration => "hw_position_with_duration",
            ActuatorKind::Temperature => "temperature",
            ActuatorKind::Spray => "spray",
            ActuatorKind::Led => "led",
        }
    }

    /// One plain sentence: what this actuator physically does.
    /// Wording follows the buttplug platform documentation's output
    /// model; it describes the actuator class, never a specific
    /// product's marketing claim.
    pub fn what_it_does(self) -> &'static str {
        match self {
            ActuatorKind::Vibrate => {
                "a motor that vibrates; the level sets how strong the vibration is"
            }
            ActuatorKind::Oscillate => {
                "a mechanism that thrusts or strokes back and forth; the level sets the pace and depth of the stroke"
            }
            ActuatorKind::Rotate => "a part that rotates; the level sets the rotation speed",
            ActuatorKind::Constrict => {
                "a cuff or chamber that squeezes; the level sets how tight the squeeze is"
            }
            ActuatorKind::Inflate => "a chamber that inflates; the level sets how full it gets",
            ActuatorKind::Position => {
                "a part that moves to a position; the level sets where along its travel it sits"
            }
            ActuatorKind::HwPositionWithDuration => {
                "a part that moves to a position over a set duration; the level sets the target position"
            }
            ActuatorKind::Temperature => {
                "a surface that warms or cools; the level sets the temperature step"
            }
            ActuatorKind::Spray => {
                "a pump that sprays (lubricant or water, by design); the level sets the spray strength"
            }
            ActuatorKind::Led => "a light; the level sets its brightness — ambience, not sensation",
        }
    }
}

/// One output feature of a device: an actuator, its step range in the
/// config's own units, and the config's descriptor text if it has one.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct OutputFeature {
    pub kind: ActuatorKind,
    pub min: i32,
    pub max: i32,
    pub descriptor: String,
}

/// The capability record for one catalogue device.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct DeviceFeatures {
    pub brand: String,
    pub name: String,
    /// Form-factor family (presentation metadata from the IoST type;
    /// keys the family art, the turntables, and the trial's kind
    /// limits — it is not a capability claim).
    pub family: String,
    pub match_kind: MatchKind,
    pub outputs: Vec<OutputFeature>,
    /// Sensor/input kinds the config lists (e.g. "battery").
    pub inputs: Vec<String>,
}

impl DeviceFeatures {
    /// The strongest sensation-bearing actuator, for summaries: the
    /// first output that is not an LED. `None` when the config lists
    /// no outputs at all.
    pub fn primary_output(&self) -> Option<&OutputFeature> {
        self.outputs
            .iter()
            .find(|f| f.kind != ActuatorKind::Led)
            .or_else(|| self.outputs.first())
    }
}

/// Why the features table could not be parsed.
#[derive(Debug)]
pub enum FeaturesError {
    /// A row did not have exactly [`FIELD_COUNT`] fields.
    FieldCount { line: usize, found: usize },
    /// A match cell held an unknown label.
    UnknownMatch { line: usize, text: String },
    /// An output cell was not `kind:min..max:descriptor`.
    BadOutput { line: usize, text: String },
    /// An output kind token was unknown.
    UnknownKind { line: usize, text: String },
}

impl fmt::Display for FeaturesError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            FeaturesError::FieldCount { line, found } => {
                write!(f, "line {line}: {found} fields, expected {FIELD_COUNT}")
            }
            FeaturesError::UnknownMatch { line, text } => {
                write!(f, "line {line}: unknown match label {text:?}")
            }
            FeaturesError::BadOutput { line, text } => {
                write!(f, "line {line}: malformed output cell {text:?}")
            }
            FeaturesError::UnknownKind { line, text } => {
                write!(f, "line {line}: unknown actuator kind {text:?}")
            }
        }
    }
}

impl std::error::Error for FeaturesError {}

/// Parses the features TSV into records, in file order. The first
/// violation aborts the whole parse — a partially loaded table is
/// never published, same discipline as the catalogue parser.
pub fn parse_features(tsv: &str) -> Result<Vec<DeviceFeatures>, FeaturesError> {
    let mut records = Vec::new();
    for (index, line) in tsv.lines().enumerate() {
        let line_no = index + 1;
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let fields: Vec<&str> = line.split('\t').collect();
        if fields.len() != FIELD_COUNT {
            return Err(FeaturesError::FieldCount {
                line: line_no,
                found: fields.len(),
            });
        }
        let match_kind =
            MatchKind::parse(fields[3]).ok_or_else(|| FeaturesError::UnknownMatch {
                line: line_no,
                text: fields[3].to_owned(),
            })?;
        let mut outputs = Vec::new();
        if !fields[4].is_empty() {
            for cell in fields[4].split(',') {
                let mut parts = cell.splitn(3, ':');
                let kind_text = parts.next().unwrap_or_default();
                let range_text = parts.next().unwrap_or_default();
                let descriptor = parts.next().unwrap_or_default();
                let kind =
                    ActuatorKind::parse(kind_text).ok_or_else(|| FeaturesError::UnknownKind {
                        line: line_no,
                        text: kind_text.to_owned(),
                    })?;
                let (min_text, max_text) =
                    range_text
                        .split_once("..")
                        .ok_or_else(|| FeaturesError::BadOutput {
                            line: line_no,
                            text: cell.to_owned(),
                        })?;
                let parse_step = |t: &str| {
                    t.parse::<i32>().map_err(|_| FeaturesError::BadOutput {
                        line: line_no,
                        text: cell.to_owned(),
                    })
                };
                outputs.push(OutputFeature {
                    kind,
                    min: parse_step(min_text)?,
                    max: parse_step(max_text)?,
                    descriptor: descriptor.to_owned(),
                });
            }
        }
        let inputs = if fields[5].is_empty() {
            Vec::new()
        } else {
            fields[5].split(',').map(str::to_owned).collect()
        };
        records.push(DeviceFeatures {
            brand: fields[0].to_owned(),
            name: fields[1].to_owned(),
            family: fields[2].to_owned(),
            match_kind,
            outputs,
            inputs,
        });
    }
    Ok(records)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::catalogue::{CATALOGUE_TSV, parse_catalogue};

    fn embedded() -> Vec<DeviceFeatures> {
        parse_features(FEATURES_TSV).expect("embedded features must parse")
    }

    #[test]
    fn features_align_with_catalogue_rows() {
        let devices = parse_catalogue(CATALOGUE_TSV).expect("catalogue parses");
        let features = embedded();
        assert_eq!(features.len(), devices.len());
        for (device, record) in devices.iter().zip(features.iter()) {
            assert_eq!(device.brand, record.brand);
            assert_eq!(device.name, record.name);
        }
    }

    #[test]
    fn matched_devices_carry_real_outputs() {
        let features = embedded();
        let with_outputs = features.iter().filter(|r| !r.outputs.is_empty()).count();
        // Census of record (generator, 2026-11-27): 285 of 471 rows
        // matched a config entry with at least one output feature.
        assert_eq!(with_outputs, 285);
        let unmatched = features
            .iter()
            .filter(|r| r.match_kind == MatchKind::None)
            .count();
        assert_eq!(unmatched, 186);
        for record in features.iter().filter(|r| r.match_kind == MatchKind::None) {
            assert!(
                record.outputs.is_empty(),
                "unmatched device {} {} must not carry invented features",
                record.brand,
                record.name
            );
        }
    }

    #[test]
    fn every_family_label_is_known_to_the_art_pipeline() {
        let known = [
            "egg",
            "insertable",
            "rabbit",
            "plug",
            "panty",
            "suction",
            "butterfly",
            "kegel",
            "bullet",
            "wand",
            "clip",
            "external",
            "rideon",
            "nipple",
            "beads",
            "controller",
            "other",
        ];
        for record in embedded() {
            assert!(
                known.contains(&record.family.as_str()),
                "unknown family {}",
                record.family
            );
        }
    }

    #[test]
    fn parse_rejects_malformed_rows() {
        assert!(parse_features("a\tb\tc\n").is_err());
        assert!(parse_features("A\tB\tegg\tbogus\t\t\n").is_err());
        assert!(parse_features("A\tB\tegg\texact\tfly:0-9:\t\n").is_err());
        assert!(parse_features("A\tB\tegg\texact\tvibrate:0\t\n").is_err());
        let one = parse_features("A\tB\tegg\texact\tvibrate:0..20:tip\tbattery\n")
            .expect("well-formed row parses");
        assert_eq!(one[0].outputs.len(), 1);
        assert_eq!(one[0].outputs[0].max, 20);
        assert_eq!(one[0].inputs, vec!["battery".to_string()]);
    }
}
